// Modelo de la VPC del laboratorio: una subred pública y una instancia bastión.
// El SSH desde la red de administración no consigue entrar.
export const vpc = {
  cidr: "10.0.0.0/16",
  subnets: [
    {
      id: "subnet-publica",
      cidr: "10.0.0.0/24",
      routes: [
        { destination: "10.0.0.0/16", target: "local" },
        { destination: "0.0.0.0/0", target: "igw-0a1b2c3d4e5f60718" },
      ],
      nacl: [
        { direction: "inbound", number: 100, action: "allow", protocol: "-1", cidr: "0.0.0.0/0" },
        { direction: "outbound", number: 100, action: "allow", protocol: "-1", cidr: "0.0.0.0/0" },
      ],
    },
  ],
  securityGroups: [
    {
      id: "sg-bastion",
      rules: [
        { direction: "inbound", protocol: "tcp", fromPort: 2222, toPort: 2222, cidr: "203.0.113.0/24" },
        { direction: "outbound", protocol: "-1", cidr: "0.0.0.0/0" },
      ],
    },
  ],
};

solution.code:
// Modelo de la VPC del laboratorio: la regla de entrada ahora apunta al puerto de SSH.
export const vpc = {
  cidr: "10.0.0.0/16",
  subnets: [
    {
      id: "subnet-publica",
      cidr: "10.0.0.0/24",
      routes: [
        { destination: "10.0.0.0/16", target: "local" },
        { destination: "0.0.0.0/0", target: "igw-0a1b2c3d4e5f60718" },
      ],
      nacl: [
        { direction: "inbound", number: 100, action: "allow", protocol: "-1", cidr: "0.0.0.0/0" },
        { direction: "outbound", number: 100, action: "allow", protocol: "-1", cidr: "0.0.0.0/0" },
      ],
    },
  ],
  securityGroups: [
    {
      id: "sg-bastion",
      rules: [
        { direction: "inbound", protocol: "tcp", fromPort: 22, toPort: 22, cidr: "203.0.113.0/24" },
        { direction: "outbound", protocol: "-1", cidr: "0.0.0.0/0" },
      ],
    },
  ],
};

spec.code:
const bastion = { ip: "10.0.0.10", securityGroups: ["sg-bastion"] };
const admin = { ip: "203.0.113.24" };
const ssh = aws.network.canConnect(vpc, { from: admin, to: bastion, protocol: "tcp", port: 22 });
assert.strictEqual(ssh.allowed, true, "El SSH desde la red de administración no llega: " + ssh.reason);

const reglas = vpc.securityGroups[0].rules;
const entradas = reglas.filter((regla: { direction: string }) => regla.direction === "inbound");
assert.strictEqual(entradas.length, 1, "Debe quedar una sola regla de entrada");
assert.strictEqual(entradas[0].cidr, "203.0.113.0/24", "El origen de la regla de entrada debe seguir siendo la red de administración");

const regla = vpc.securityGroups[0].rules.find((candidata: { direction: string }) => candidata.direction === "inbound");
assert.ok(regla, "Falta la regla de entrada del security group");
assert.strictEqual(regla.protocol, "tcp");
assert.strictEqual(regla.fromPort, 22);
assert.strictEqual(regla.toPort, 22);

const bastion = { ip: "10.0.0.10", securityGroups: ["sg-bastion"] };
const ssh = aws.network.canConnect(vpc, { from: { ip: "198.51.100.7" }, to: bastion, protocol: "tcp", port: 22 });
assert.strictEqual(ssh.allowed, false, "El 22 no puede quedar abierto a cualquier dirección");
const puertoViejo = aws.network.canConnect(vpc, { from: { ip: "203.0.113.24" }, to: bastion, protocol: "tcp", port: 2222 });
assert.strictEqual(puertoViejo.allowed, false, "El 2222 no es el puerto de SSH y no debe quedar permitido");

const nacl = vpc.subnets[0].nacl;
const entrada = aws.network.naclAllows(nacl, { direction: "inbound", protocol: "tcp", port: 22, peer: "203.0.113.24" });
assert.strictEqual(entrada.allowed, true, "La NACL debe permitir la entrada al 22: " + entrada.reason);
const salida = aws.network.naclAllows(nacl, { direction: "outbound", protocol: "tcp", port: 49152, peer: "203.0.113.24" });
assert.strictEqual(salida.allowed, true, "La NACL debe permitir la respuesta al puerto efímero: " + salida.reason);

