// Entrega del sitio: certificado en us-east-1 para CloudFront y listener del origen en HTTPS.
export const sitio = {
  dominio: "www.ejemplo.com",
  distribucion: {
    servicio: "cloudfront",
    certificado: { proveedor: "acm", region: "us-east-1", dominio: "www.ejemplo.com" },
  },
  origen: {
    balanceador: "alb",
    listener: { protocolo: "HTTPS", certificado: "www.ejemplo.com" },
  },
  registroDns: { nombre: "www.ejemplo.com", tipo: "A", alias: true },
};

spec.code:
const certificado = sitio.distribucion.certificado;
assert.strictEqual(certificado.proveedor, "acm", "La distribución usa un certificado de ACM");
assert.strictEqual(certificado.region, "us-east-1", "CloudFront exige el certificado en us-east-1 y el modelo lo pide en " + certificado.region);

const listener = sitio.origen.listener;
assert.strictEqual(listener.protocolo, "HTTPS", "El listener sigue en " + listener.protocolo + " y no termina TLS");
assert.strictEqual(listener.certificado, sitio.dominio, "El listener debe presentar el certificado de " + sitio.dominio);
